import{_ as a,c as t,o as i,a1 as l}from"./chunks/framework.DvAN0E7D.js";const m=JSON.parse('{"title":"AI 智能生成表单","description":"","frontmatter":{},"headers":[],"relativePath":"ai-guide.md","filePath":"ai-guide.md"}'),d={name:"ai-guide.md"};function o(c,e,r,s,n,h){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="ai-智能生成表单" tabindex="-1">AI 智能生成表单 <a class="header-anchor" href="#ai-智能生成表单" aria-label="Permalink to “AI 智能生成表单”">​</a></h1><p>form-cook 内置了 AI 生成表单能力，你只需用自然语言描述想要的表单，即可自动生成对应的表单 Schema，预览确认后一键应用到画布。</p><h2 id="功能入口" tabindex="-1">功能入口 <a class="header-anchor" href="#功能入口" aria-label="Permalink to “功能入口”">​</a></h2><p>打开设计器后，点击顶部工具栏左侧的 <strong>AI</strong> 按钮，即可打开「AI 生成表单」弹窗。</p><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to “使用流程”">​</a></h2><ol><li>在左侧输入框中描述你想生成的表单需求，例如： <ul><li><code>生成一个员工入职表单，包含姓名、手机号、部门、职位、入职日期、紧急联系人</code></li><li><code>帮我做一个活动报名表，需要姓名、手机号、邮箱、公司、参与场次、备注</code></li><li><code>生成一个请假申请表，包含申请人、部门、请假类型、开始日期、结束日期、请假事由、审批人</code></li></ul></li><li>点击「生成表单」按钮，等待生成完成。</li><li>在右侧「生成结果预览」中查看生成的 Schema 结构与摘要说明。</li><li>确认无误后点击「应用到画布」，即可将生成的表单替换到当前画布。</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>弹窗内置了若干示例提示词，点击标签可快速填入输入框，方便体验。</p></div><h2 id="两种生成模式" tabindex="-1">两种生成模式 <a class="header-anchor" href="#两种生成模式" aria-label="Permalink to “两种生成模式”">​</a></h2><p>AI 生成支持两种模式，可在弹窗右侧的「模型配置」中切换：</p><h3 id="本地规则模式-默认" tabindex="-1">本地规则模式（默认） <a class="header-anchor" href="#本地规则模式-默认" aria-label="Permalink to “本地规则模式（默认）”">​</a></h3><p>无需配置任何模型或密钥，开箱即用。适合先体验完整流程，或在没有大模型服务时使用。</p><ul><li>优点：零配置、响应快、稳定不依赖网络</li><li>局限：基于内置的字段词库与场景模板生成，理解能力有限，复杂需求建议使用大模型模式</li></ul><h3 id="openai-兼容接口模式" tabindex="-1">OpenAI 兼容接口模式 <a class="header-anchor" href="#openai-兼容接口模式" aria-label="Permalink to “OpenAI 兼容接口模式”">​</a></h3><p>连接你自己的大模型服务，生成能力更强、更灵活。</p><p>支持的服务商预设：</p><table tabindex="0"><thead><tr><th>服务商</th><th>默认 Base URL</th><th>默认模型</th></tr></thead><tbody><tr><td>OpenAI</td><td><code>https://api.openai.com/v1</code></td><td><code>gpt-4o-mini</code></td></tr><tr><td>DeepSeek</td><td><code>https://api.deepseek.com/v1</code></td><td><code>deepseek-chat</code></td></tr><tr><td>硅基流动</td><td><code>https://api.siliconflow.cn/v1</code></td><td><code>deepseek-ai/DeepSeek-V3</code></td></tr><tr><td>自定义</td><td>自行填写</td><td>自行填写</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全提示</p><p>API Key 默认仅保存在当前浏览器的 <code>localStorage</code> 中。默认情况下不会保存 API Key，需要手动勾选「记住 API Key 到本地浏览器」才会持久化。请勿在公共设备上保存密钥。</p></div><h2 id="配置大模型" tabindex="-1">配置大模型 <a class="header-anchor" href="#配置大模型" aria-label="Permalink to “配置大模型”">​</a></h2><ol><li>切换到「OpenAI 兼容接口」模式。</li><li>选择服务商预设（或选择「自定义」后手动填写）。</li><li>填写或确认 <code>Base URL</code>、<code>模型名称</code>、<code>API Key</code>。</li><li>可选：调整 <code>Temperature</code>（0 ~ 1，越低越稳定）。</li><li>配置完成后即可在输入框中描述需求并生成。</li></ol><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>配置会自动保存到本地浏览器。切换服务商预设时，<code>Base URL</code> 和 <code>模型名称</code> 会自动填充为该服务商的默认值。</p></div><h2 id="生成结果说明" tabindex="-1">生成结果说明 <a class="header-anchor" href="#生成结果说明" aria-label="Permalink to “生成结果说明”">​</a></h2><p>生成结果包含三个部分：</p><ul><li><strong>摘要（summary）</strong>：对本次生成的简短说明，例如生成了多少个字段、基于什么场景。</li><li><strong>警告（warnings）</strong>：需要你留意的提示，例如当前使用的是本地规则、字段校验需要继续细化等。</li><li><strong>Schema 预览</strong>：完整的表单 JSON 结构，采用只读代码编辑器展示，方便核对。</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>应用到画布时会<strong>替换</strong>当前画布内容，建议先保存当前表单再使用 AI 生成。</li><li>大模型返回的字段校验规则、远程数据源、复杂联动等可能需要你在右侧配置面板中继续细化。</li><li>使用 OpenAI 兼容接口模式时，请确保你的网络可以访问所配置的 Base URL。</li></ul>',25)])])}const b=a(d,[["render",o]]);export{m as __pageData,b as default};
